export const getAuthChangePasswordUrl = () => {
  return `/api/auth/change-password`;
};

/**
 * `currentPassword` is required unless the user is on a forced change
 * (admin-issued temporary password), in which case only `newPassword` is read.
 * @summary Change the signed-in user's password
 */
export const authChangePassword = async (
  authChangePasswordRequest: AuthChangePasswordRequest,
  options?: Parameters<typeof customFetch>[1],
): Promise<AuthChangePasswordResult> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<
      string | readonly string[] | undefined
    >(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return customFetch<AuthChangePasswordResult>(getAuthChangePasswordUrl(), {
    ...options,
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      ...getHeaders(options?.headers),
    },
    body: JSON.stringify(authChangePasswordRequest),
  });
};

