/**
 * Write or delete implies read. All three false removes the grant.
 * @summary Grant or change one user's access to a node (Super Admin or Company Admin only)
 */
export const putVizTreeNodeShare = async (
  id: string,
  userId: string,
  vizTreeShareFlags: VizTreeShareFlags,
  options?: Parameters<typeof customFetch>[1],
): Promise<VizTreeShareGrant> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<
      string | readonly string[] | undefined
    >(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return customFetch<VizTreeShareGrant>(getPutVizTreeNodeShareUrl(id, userId), {
    ...options,
    method: "PUT",
    headers: {
      "Content-Type": "application/json",
      ...getHeaders(options?.headers),
    },
    body: JSON.stringify(vizTreeShareFlags),
  });
};

