export const getCreateUploadsUrl = () => {
  return `/api/uploads`;
};

/**
 * Each file is type-checked by content, image-checked and (when enabled)
 * malware-scanned. Bad files are rejected individually; the request fails
 * with 400 only when no file was stored. Size and count limits come from
 * UPLOAD_MAX_BYTES (default 10 MiB) and UPLOAD_MAX_FILES (default 5).
 * @summary Upload one or more files (multipart/form-data, any field name)
 */
export const createUploads = async (
  uploadFilesForm: UploadFilesForm,
  options?: Parameters<typeof customFetch>[1],
): Promise<UploadBatchResult> => {
  const formData = new FormData();

  return customFetch<UploadBatchResult>(getCreateUploadsUrl(), {
    ...options,
    method: "POST",
    body: formData,
  });
};

export const getCreateUploadsMutationKey = () => ["createUploads"] as const;

